export const LOADERS: LoaderKind[] = ["vanilla", "fabric", "quilt", "forge", "neoforge"];

export function isErrorInfo(e: unknown): e is ErrorInfo {
  return !!e && typeof e === "object" && "code" in e && "message" in e;
}

export function toErrorInfo(e: unknown): ErrorInfo {
  if (isErrorInfo(e)) return e;
  return { code: "generic", message: e instanceof Error ? e.message : String(e), params: {} };
}

/** Human, translated message for an error from the backend. */
export function errorMessage(e: unknown): string {
  const info = toErrorInfo(e);
  const key = `errors.${info.code}`;
  const params: Record<string, string> = { ...info.params, message: info.message };
  if (info.code === "auth.xsts" && !params.code) params.code = info.message.match(/\d+/)?.[0] ?? "?";
  return has(key) ? t(key, params) : info.message;
}

const IS_WINDOWS = navigator.userAgent.includes("Windows");

function b64url(s: string): string {
  const bytes = new TextEncoder().encode(s);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

const LOCAL_IMG = IS_WINDOWS ? "http://localimg.localhost/" : "localimg://localhost/";

/** Route a remote image through the backend proxy (`img://`), which the CSP allows. */
export function imgUrl(url: string | null | undefined, opts?: { noCache?: boolean }): string | undefined {
  if (!url) return undefined;
  if (url.startsWith("data:") || url.startsWith("blob:") || url.startsWith(LOCAL_IMG)) return url;
  if (!/^https?:\/\//i.test(url)) return undefined;
  const base = IS_WINDOWS ? "http://img.localhost/" : "img://localhost/";
  return base + b64url(url) + (opts?.noCache ? "?nc=1" : "");
}

/** Images of CurseForge content must not be cached (API terms). */
export function providerImg(provider: Provider, url: string | null | undefined): string | undefined {
  return imgUrl(url, { noCache: provider === "curseforge" });
}

/** A custom instance icon (`icon: "file:…"`), served from the instance folder. */
export function instanceIconUrl(id: string, icon: string | null | undefined): string | undefined {
  const file = icon?.startsWith("file:") ? icon.slice(5) : null;
  return file ? `${LOCAL_IMG}instance/${encodeURIComponent(id)}/${encodeURIComponent(file)}` : undefined;
}

/** A Minecraft texture (`item/diamond`), read by the backend from a Mojang client jar. */
export function textureUrl(texture: string): string {
  return `${LOCAL_IMG}mc/${texture.split("/").map(encodeURIComponent).join("/")}`;
}

export function screenshotUrl(id: string, name: string): string {
  return `${LOCAL_IMG}instance/${encodeURIComponent(id)}/screenshots/${encodeURIComponent(name)}`;
}

export function worldIconUrl(id: string, folder: string): string {
  return `${LOCAL_IMG}instance/${encodeURIComponent(id)}/world/${encodeURIComponent(folder)}`;
}

/** A skin from the launcher's skin library. */
export function savedSkinUrl(id: string): string {
  return `${LOCAL_IMG}skin/${encodeURIComponent(id)}`;
}

export function themeAssetUrl(name: string): string {
  return (IS_WINDOWS ? "http://themeasset.localhost/" : "themeasset://localhost/") + encodeURIComponent(name);
}

export function loaderLabel(l: LoaderKind | string): string {
  return t(`loaders.${l}`);
}

export function instanceVersionLabel(i: Pick<Instance, "gameVersion" | "loader" | "loaderVersion">): string {
  return i.loader === "vanilla" ? i.gameVersion : `${i.gameVersion} · ${loaderLabel(i.loader)}`;
}

/** "Name · 1.21.11 · Fabric", leaving out the version or loader when the name already says it. */
export function instanceTitle(
  i: Pick<Instance, "name" | "gameVersion" | "loader" | "loaderVersion">,
): string {
  const name = i.name.toLowerCase();
  const parts = [i.name];
  if (!name.includes(i.gameVersion.toLowerCase())) parts.push(i.gameVersion);
  if (i.loader !== "vanilla") {
    const loader = loaderLabel(i.loader);
    if (!name.includes(loader.toLowerCase())) parts.push(loader);
  }
  return parts.join(" · ");
}

/** Default Steve skin, fetched at runtime from Mojang's texture server (never bundled). */
export const DEFAULT_SKIN =
  "https://textures.minecraft.net/texture/31f477eb1a7beee631c2ca64d06f8f68fa93a3386d04452ab27f43acdf1b60cb";
